import { toolCall } from '@astral-mcp/tools';
const items = [[64,["documentation","needs-triage"]],[60,["enhancement"]],[58,["bug"]],[55,[]],[51,[]],[49,[]],[47,["enhancement"]],[45,[]],[43,["bug"]],[39,["enhancement"]],[34,[]],[32,[]]];
export default setup({}).createMachine({
  context: { n: 0 },
  initial: 'w',
  states: {
    w: {
      entry: enqueueActions(({ enqueue }) => {
        items.forEach(([num, labels], i) => enqueue(toolCall('github.issue_write', { method: 'update', owner: 'acme', repo: 'widgets', issue_number: num, labels: [...labels, 'stale'] }, { id: 'i' + i })));
