import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
const nums=[146,144,142,140,139,137,12,11,135,10,134,8,132,131,128,127,125,124,123,121,120,117,116,114,113,111];
export default setup({}).createMachine({
  id:'m',
  context:{hits:[],done:0,c:0,fail:[]},
  initial:'read',
  states:{
    read:{
      entry:enqueueActions(({enqueue})=>{nums.forEach(n=>enqueue(toolCall('github.pull_request_read',{method:'get_files',owner:'acme',repo:'widgets',pullNumber:n,perPage:100},{id:'r'+n})));}),
      on:{
        TOOL_RESULT:{actions:assign(({context,event})=>{
          let r=event.result; if(typeof r==='string'){try{r=JSON.parse(r)}catch(e){r=[]}}
          const n=Number(event.callId.slice(1));
          const hit=Array.isArray(r)&&r.some(f=>f.filename&&f.filename.startsWith('src/export/'));
          return {done:context.done+1,hits:hit?[...context.hits,n]:context.hits};
        })},
        TOOL_ERROR:{actions:assign(({context,event})=>({done:context.done+1,fail:[...context.fail,event.callId]}))},
      },
      always:{guard:({context})=>context.done===nums.length,target:'write'}
    },
    write:{
      entry:enqueueActions(({context,enqueue})=>{context.hits.forEach(n=>enqueue(toolCall('github.add_issue_comment',{owner:'acme',repo:'widgets',issue_number:n,body:'Please add a CHANGELOG entry for the export changes.'},{id:'w'+n})));}),
      on:{
        TOOL_RESULT:{actions:assign({c:({context})=>context.c+1})},
        TOOL_DENIED:{actions:assign({c:({context})=>context.c+1})},
        TOOL_ERROR:{actions:assign({c:({context})=>context.c+1})},
      },
      always:{guard:({context})=>context.c===context.hits.length,target:'end'}
    },
    end:{type:'final'}
  },
  output:({context})=>({hits:context.hits,fail:context.fail})
});

