        },
        "duplicate_of": {
          "type": "number",
          "description": "Issue number that this issue is a duplicate of. Required when state_reason is 'duplicate'."
        },
        "issue_fields": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "delete": {
                "type": "boolean",
